# Desafio CodeLab: Sequência de Fibonacci
# Solução iterativa O(n) com validação contra casos de teste conhecidos.

def fibonacci(n: int) -> int:
    """Retorna o n-ésimo número de Fibonacci (fib(0) = 0, fib(1) = 1)."""
    if n < 0:
        raise ValueError("n deve ser não negativo")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


if __name__ == "__main__":
    for i in range(10):
        print(i, fibonacci(i))

